output_text:
[
  {
    "id": "must_take_cart",
    "text": "A shopper should take a cart during the trip, a role-based norm that does not depend on where the cart station is located.",
    "abstraction": {
      "state_properties": {},
      "events": {}
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "hasCart"
    }
  },
  {
    "id": "no_exit_without_cart",
    "text": "A shopper must not leave the store without a cart, which is tied to the exit action rather than to any particular exit coordinate.",
    "abstraction": {
      "state_properties": {},
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "EXIT",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "retrieve_released_cart",
    "text": "If a shopper releases a cart, they must later take a cart again before leaving, regardless of where the temporary cart-staging place is.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "cartRelease": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "cartTake": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "cartRelease",
      "discharge": "cartTake"
    }
  },
  {
    "id": "no_cart_in_single_file_shelf_aisle",
    "text": "Do not push a cart in a single-file aisle flanked by shelves, because the restriction follows local aisle geometry even if shelves are moved or rotated.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "or": [
            {
              "and": [
                "shelfE",
                "shelfW",
                {
                  "le": [
                    "freeWidthH",
                    1
                  ]
                }
              ]
            },
            {
              "and": [
                "shelfN",
                "shelfS",
                {
                  "le": [
                    "freeWidthV",
                    1
                  ]
                }
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileShelfAisle"
        ]
      }
    }
  },
  {
    "id": "no_enter_single_file_with_cart",
    "text": "A shopper must not enter a single-file shelf aisle while still holding a cart, which generalizes to any narrow shelf corridor rather than one observed coordinate.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "or": [
            {
              "and": [
                "shelfE",
                "shelfW",
                {
                  "le": [
                    "freeWidthH",
                    1
                  ]
                }
              ]
            },
            {
              "and": [
                "shelfN",
                "shelfS",
                {
                  "le": [
                    "freeWidthV",
                    1
                  ]
                }
              ]
            }
          ]
        }
      },
      "events": {
        "enterSingleFileWithCart": {
          "pre": "hasCart",
          "post": {
            "and": [
              "hasCart",
              "singleFileShelfAisle"
            ]
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enterSingleFileWithCart"
    }
  },
  {
    "id": "collect_in_single_file_without_cart",
    "text": "When interacting with shelves from inside a single-file aisle, the shopper must not be encumbered by a cart, a norm based on aisle function rather than item location.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "or": [
            {
              "and": [
                "shelfE",
                "shelfW",
                {
                  "le": [
                    "freeWidthH",
                    1
                  ]
                }
              ]
            },
            {
              "and": [
                "shelfN",
                "shelfS",
                {
                  "le": [
                    "freeWidthV",
                    1
                  ]
                }
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "singleFileShelfAisle",
          "INTERACT",
          "hasCart"
        ]
      }
    }
  },
  {
    "id": "park_cart_only_in_open_area",
    "text": "A shopper may release or park a cart only in an open staging area, which is defined by local clearance and not by a fixed aisle entrance coordinate.",
    "abstraction": {
      "state_properties": {
        "openCartStagingArea": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                3
              ]
            },
            {
              "ge": [
                "freeWidthV",
                3
              ]
            },
            {
              "not": "adjShelf"
            }
          ]
        }
      },
      "events": {
        "cartRelease": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "cartRelease",
          {
            "not": "openCartStagingArea"
          }
        ]
      }
    }
  },
  {
    "id": "retrieve_after_on_foot_narrow_aisle_visit",
    "text": "After going on foot into a single-file shelf aisle, the shopper must return to an open area and take the cart again, so the rule follows the aisle type rather than the particular route.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "or": [
            {
              "and": [
                "shelfE",
                "shelfW",
                {
                  "le": [
                    "freeWidthH",
                    1
                  ]
                }
              ]
            },
            {
              "and": [
                "shelfN",
                "shelfS",
                {
                  "le": [
                    "freeWidthV",
                    1
                  ]
                }
              ]
            }
          ]
        },
        "openCartStagingArea": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                3
              ]
            },
            {
              "ge": [
                "freeWidthV",
                3
              ]
            },
            {
              "not": "adjShelf"
            }
          ]
        },
        "onFootInSingleFileAisle": {
          "and": [
            {
              "not": "hasCart"
            },
            "singleFileShelfAisle"
          ]
        }
      },
      "events": {
        "cartTakeInOpenArea": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT",
              "openCartStagingArea"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "onFootInSingleFileAisle",
      "discharge": "cartTakeInOpenArea"
    }
  }
]
